//! The glue of the `nan` component (46) for the module that hosts it, generated by `tools/gen_vtables.py` from `modules/mod_nan/API.md`; do not edit.
//!
//! [`Api`] is what the module implements. [`dispatch`] serves a request (a method number and the fields map: the runtime has parsed the
//! envelope) and [`table`] is the module's vtable for other modules, whose functions enter the allocator context of the module (`Ctx`).
#![allow(clippy::all, dead_code, unused_imports)]
use core::ffi::{c_int, c_void};
use xip_abi::{Nan, CallView, Hw, Host, ERR_ARG, ERR_SIZE, ERR_UNSUPPORTED, NanTransport};

pub const COMPONENT: i32 = 46;

/// What the module implements. Every method returns `Err(code)` with a negative `ERR_*`.
pub trait Api {
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): The runtime worker calls this after USB SOF connection state changes, to keep active roles while a host is attached by default, or follow the explicit USB detach policy.
    fn usb(&mut self, hw: &Hw, connected: u32) -> Result<(), i32>;
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): The runtime worker calls this with the native wake cause so NAN restores receive capture and active transport policy after local serial or decoded directed-packet activity.
    fn wake(&mut self, hw: &Hw, cause: i32) -> Result<(), i32>;
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): Local policy callers and the remote sleepy handler use this to select paired discovery windows; USB attachment vetoes enabling.
    fn sleepy(&mut self, hw: &Hw, enabled: u32, cadence: u32, trace: u32, immediate: u32) -> Result<(), i32>;
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): A publication supplier calls this to replace the cache without restarting synchronization or waiting for a message round trip.
    fn set_announce(&mut self, hw: &Hw, record: *const u8, len: usize) -> Result<(), i32>;
    /// Local only (reached by `get_component` callers, never by an envelope; the arguments are as given): Local control callers use this to apply validated independent Wi-Fi, UART, BLE and LoRa/FSK settings; direct transport.set requests use the same NAN policy.
    fn transport_set(&mut self, hw: &Hw, request: *const NanTransport) -> Result<(), i32>;
}

/// Serve method `method` with the request `fields`; the response map goes to `out`. Returns its length. An unknown method is `ERR_UNSUPPORTED`.
pub fn dispatch<T: Api>(t: &mut T, hw: &Hw, method: i32, fields: &[u8], out: &mut [u8]) -> Result<usize, i32> {
    let _ = (t, hw, fields, out);
    match method {
        _ => Err(ERR_UNSUPPORTED),
    }
}

/// The first argument of every function of the module's table: the host table and the module's state, both valid while the module runs.
#[repr(C)]
pub struct Ctx {
    pub host: *const Host,
    pub state: *mut u8,
}

/// Run `body` in the allocator context of the module (the runtime's thunk has taken the module's lock).
unsafe fn within<T: Api>(ctx: *mut c_void, body: impl FnOnce(&mut T, &Hw) -> Result<(), i32>) -> c_int {
    let ctx = &*(ctx as *const Ctx);
    let Some(hw) = Hw::new(ctx.host) else { return ERR_ARG };
    let saved = xip_abi::heap::enter(ctx.host);
    let rc = match body(&mut *(ctx.state as *mut T), &hw) { Ok(()) => 0, Err(rc) => rc };
    xip_abi::heap::leave(saved);
    rc
}

unsafe extern "C" fn v_usb<T: Api>(ctx: *mut c_void, connected: u32) -> c_int {
    within::<T>(ctx, |t, hw| t.usb(hw, connected))
}
unsafe extern "C" fn v_wake<T: Api>(ctx: *mut c_void, cause: i32) -> c_int {
    within::<T>(ctx, |t, hw| t.wake(hw, cause))
}
unsafe extern "C" fn v_sleepy<T: Api>(ctx: *mut c_void, enabled: u32, cadence: u32, trace: u32, immediate: u32) -> c_int {
    within::<T>(ctx, |t, hw| t.sleepy(hw, enabled, cadence, trace, immediate))
}
unsafe extern "C" fn v_set_announce<T: Api>(ctx: *mut c_void, record: *const u8, len: usize) -> c_int {
    within::<T>(ctx, |t, hw| t.set_announce(hw, record, len))
}
unsafe extern "C" fn v_transport_set<T: Api>(ctx: *mut c_void, request: *const NanTransport) -> c_int {
    within::<T>(ctx, |t, hw| t.transport_set(hw, request))
}

/// The module's table of the `nan` component and the context its functions take: a part of the module's state block. The table is built
/// when the module answers `HOST_TABLE`, not as a constant: the function addresses of a position-independent image (ESP32-C6) exist only at run time.
#[repr(C)]
pub struct Hosted {
    pub ctx: Ctx,
    pub table: Nan,
}
impl Default for Hosted {
    /// All zero: no table yet (the state block of a module starts zeroed).
    fn default() -> Self {
        unsafe { core::mem::zeroed() }
    }
}

/// Answer `HOST_TABLE` for this component with the module's table, whose functions call `T` in the module's allocator context, and the context
/// they take. `hosted` points into the module's state block (it must stay valid while the module runs) and `state` is that block as `T`.
pub fn provide<T: Api>(hw: &Hw, call: &CallView, hosted: *mut Hosted, state: *mut T) -> i32 {
    unsafe {
        (*hosted).ctx = Ctx { host: hw.as_ptr(), state: state.cast() };
        (*hosted).table = Nan {
            version: 1,
            size: core::mem::size_of::<Nan>() as u32,
            usb: Some(v_usb::<T>),
            wake: Some(v_wake::<T>),
            sleepy: Some(v_sleepy::<T>),
            set_announce: Some(v_set_announce::<T>),
            transport_set: Some(v_transport_set::<T>),
        };
        hw.provide_table(call, core::ptr::addr_of!((*hosted).table).cast(), core::ptr::addr_of_mut!((*hosted).ctx).cast(), xip_abi::schema::SCHEMA_NAN)
    }
}
